solutions.javascript:
function fib(n) {
    let a = 0, b = 1;
    for (let i = 0; i < n; i++) {
        let c = (a + b) % 1000000007;
        [a, b] = [b, c];
    }
    return a;
}

solutions.java:
class Solution {
    public int fib(int n) {
        int a = 0, b = 1;
        while (n-- > 0) {
            int c = (a + b) % 1000000007;
            a = b;
            b = c;
        }
        return a;
    }
}

